for (const oldIcon of document.querySelectorAll("i.bi")) {
  const id = Array.from(oldIcon.classList).find((name) => name.startsWith("bi-"))?.slice(3);
  const source = VERIFIEDNG_CLASSIC_ICONS[id];
  if (!source) continue;
  const fragment = document.createElement("template");
  fragment.innerHTML = source;
  const svg = fragment.content.firstElementChild;
  if (!svg || svg.localName !== "svg") continue;
  svg.setAttribute("width", "1em"); svg.setAttribute("height", "1em");
  svg.setAttribute("aria-hidden", oldIcon.getAttribute("aria-hidden") || "true");
  svg.style.verticalAlign = "-.125em";
  oldIcon.replaceWith(svg);
}
